import { spawn } from 'node:child_process';
import net from 'node:net';
import { mkdtempSync, writeFileSync, readFileSync, mkdirSync, rmSync, existsSync, readdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const SERVER = '/root/bench-runs/h4-c3e12a23/server.mjs';
const results = [];
const check = (name, ok, info = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${ok ? '' : ' :: ' + info}`);

function run(env, cwd) {
  return new Promise((res) => {
    const p = spawn(process.execPath, [SERVER], { env: { PATH: process.env.PATH, ...env }, cwd });
    let out = '', err = '';
    p.stdout.on('data', (d) => { out += d; });
    p.stderr.on('data', (d) => { err += d; });
    p.on('exit', (code) => res({ code, out, err }));
    setTimeout(() => p.kill(), 3000);
  });
}

function start(env, cwd) {
  return new Promise((res, rej) => {
    const p = spawn(process.execPath, [SERVER], { env: { PATH: process.env.PATH, PORT: '0', ...env }, cwd });
    let out = '';
    p.stdout.on('data', (d) => {
      out += d;
      const m = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/.exec(out);
      if (m) res({ p, port: Number(m[1]), get out() { return out; } });
    });
    p.on('exit', (c) => rej(new Error('exited ' + c)));
  });
}

function raw(port, text) {
  return new Promise((res) => {
    const s = net.connect(port, '127.0.0.1');
    let data = '';
    s.on('data', (d) => { data += d; });
    s.on('error', (e) => res({ error: e.code, data }));
    s.on('end', () => res({ data }));
    s.write(text);
  });
}

async function req(port, method, path, { body, type, headers = {} } = {}) {
  const h = { ...headers };
  if (type) h['Content-Type'] = type;
  const r = await fetch(`http://127.0.0.1:${port}${path}`, { method, headers: h, body });
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch { json = undefined; }
  return { status: r.status, ct: r.headers.get('content-type'), text, json };
}
const post = (port, obj, type = 'application/json') =>
  req(port, 'POST', '/api/bookings', { body: typeof obj === 'string' ? obj : JSON.stringify(obj), type });
const B = (o = {}) => ({ room: 'Aurora', title: 'T', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

const dir = () => mkdtempSync(join(tmpdir(), 'bk-'));

// 2. PORT
for (const bad of ['abc', '-1', '65536', ' 80', '1e3', '99999999999999999999']) {
  const r = await run({ PORT: bad }, dir());
  check(`bad PORT ${JSON.stringify(bad)}`, r.code === 1 && r.out === '' && r.err.split('\n').length === 2, JSON.stringify(r));
}
{
  const s = await start({}, dir());
  const r = await run({ PORT: String(s.port) }, dir());
  check('port in use', r.code === 1 && r.out === '' && r.err.split('\n').length === 2, JSON.stringify(r));
  s.p.kill();
}
// 3. DATA_FILE
for (const [name, content, isDir] of [
  ['dir', null, true], ['empty', ''], ['null', 'null'], ['arr', '[]'], ['bad', '{'],
  ['extra', '{"nextId":1,"bookings":[],"x":1}'],
  ['dup', '{"nextId":5,"bookings":[{"id":1,"room":"Aurora","title":"a","date":"2026-01-01","start":"09:00","end":"10:00"},{"id":1,"room":"Aurora","title":"a","date":"2026-01-02","start":"09:00","end":"10:00"}]}'],
  ['idge', '{"nextId":1,"bookings":[{"id":1,"room":"Aurora","title":"a","date":"2026-01-01","start":"09:00","end":"10:00"}]}'],
]) {
  const d = dir();
  if (isDir) mkdirSync(join(d, 'x.json')); else writeFileSync(join(d, 'x.json'), content);
  const r = await run({ DATA_FILE: 'x.json', PORT: '0' }, d);
  check(`datafile ${name}`, r.code === 1 && r.out === '' && r.err === 'cannot read data file x.json\n', JSON.stringify(r));
}
{
  const d = dir();
  const r = await run({ PORT: '0' }, d);
  check('default bookings.json error name', true);
  writeFileSync(join(d, 'bookings.json'), 'x');
  const r2 = await run({ PORT: '0' }, d);
  check('default name in msg', r2.err === 'cannot read data file bookings.json\n' && r2.code === 1, JSON.stringify(r2));
  void r;
}
{
  const d = dir();
  const s = await start({ DATA_FILE: 'nofolder/x.json' }, d);
  const r = await req(s.port, 'GET', '/api/bookings');
  check('missing folder starts empty', r.status === 200 && r.json.bookings.length === 0);
  check('no write at startup', readdirSync(d).length === 0);
  const f = await post(s.port, B());
  check('save failure 500', f.status === 500 && f.json.error === 'internal error' && f.ct === 'application/json; charset=utf-8', JSON.stringify(f));
  mkdirSync(join(d, 'nofolder'));
  const ok = await post(s.port, B());
  check('id not consumed after failure', ok.status === 201 && ok.json.id === 1, JSON.stringify(ok));
  s.p.kill();
}
// main instance
const d = dir();
const s = await start({ DATA_FILE: 'data.json' }, d);
const P = s.port;
{
  const r = await req(P, 'GET', '/api/rooms');
  check('rooms', r.status === 200 && r.ct === 'application/json; charset=utf-8' && JSON.stringify(r.json) === '{"rooms":["Aurora","Borealis","Cosmos"]}');
}
// 5 rules
const ex = async (name, r, status, msg) => check(name, r.status === status && r.json?.error === msg && r.ct === 'application/json; charset=utf-8', `${r.status} ${r.text}`);
await ex('415 missing', await req(P, 'POST', '/api/bookings', { body: JSON.stringify(B()) }), 415, 'content type must be application/json');
await ex('415 text/plain', await post(P, B(), 'text/plain'), 415, 'content type must be application/json');
{ const r = await post(P, B({ date: '2030-01-01' }), ' \tApplication/JSON\t ; charset=x'); check('ct variants ok', r.status === 201, r.text); }
await ex('415 before 413', await post(P, 'x'.repeat(10001), 'text/plain'), 415, 'content type must be application/json');
await ex('413', await post(P, 'x'.repeat(10001)), 413, 'body too large');
{
  const base = JSON.stringify(B({ date: '2030-01-02' }));
  const body = base.slice(0, -1) + ',"pad":"' + 'x'.repeat(10000 - base.length - 9) + '"}';
  const r = await post(P, body);
  check('10000 bytes ok', Buffer.byteLength(body) === 10000 && r.status === 201, `${Buffer.byteLength(body)} ${r.status}`);
}
await ex('BOM', await post(P, '﻿' + JSON.stringify(B())), 400, 'body must be a JSON object');
for (const v of ['', 'null', '[]', '1', '"s"', 'true', '{']) await ex(`not object ${v}`, await post(P, v), 400, 'body must be a JSON object');
await ex('room case', await post(P, B({ room: 'aurora' })), 400, 'room must be one of Aurora, Borealis, Cosmos');
await ex('title 81', await post(P, B({ title: 'x'.repeat(81) })), 400, 'title must be 1 to 80 characters');
await ex('title blank', await post(P, B({ title: '   ' })), 400, 'title must be 1 to 80 characters');
await ex('title num', await post(P, B({ title: 5 })), 400, 'title must be 1 to 80 characters');
await ex('date 2100', await post(P, B({ date: '2100-01-01' })), 400, 'date must be a valid YYYY-MM-DD date');
await ex('date 2001-02-29', await post(P, B({ date: '2001-02-29' })), 400, 'date must be a valid YYYY-MM-DD date');
await ex('date space', await post(P, B({ date: ' 2026-11-03' })), 400, 'date must be a valid YYYY-MM-DD date');
await ex('start 9:00', await post(P, B({ start: '9:00' })), 400, 'start must be HH:MM');
await ex('start 24:00', await post(P, B({ start: '24:00' })), 400, 'start must be HH:MM');
