await ex('rule order room before title', await post(P, B({ room: 'x', title: '' })), 400, 'room must be one of Aurora, Borealis, Cosmos');
{
  const r = await post(P, B({ date: '2000-02-29', title: '  Hi  ', extra: 1 }));
  check('leap + trimmed', r.status === 201 && r.json.title === 'Hi' && Object.keys(r.json).join() === 'id,room,title,date,start,end', r.text);
}
await post(P, B({ start: '10:00', end: '11:00' }));
await post(P, B({ start: '09:00', end: '10:00' }));
{
  const r = await post(P, B({ start: '09:30', end: '10:30' }));
  check('409 earliest', r.status === 409 && r.json.error === 'room is already booked from 09:00 to 10:00', r.text);
  const t = await post(P, B({ start: '11:00', end: '12:00' }));
  check('touching ok', t.status === 201, t.text);
}
await post(P, B({ room: 'Cosmos', start: '08:00', end: '09:00' }));
await post(P, B({ room: 'Borealis', start: '08:00', end: '09:00' }));
{
  const r = await req(P, 'GET', '/api/bookings');
  const keys = r.json.bookings.map((b) => `${b.date} ${b.start} ${b.room}`);
  const sorted = [...keys].sort((a, b) => {
