  check('sorted', JSON.stringify(keys) === JSON.stringify(sorted), keys.join('|'));
  const f = await req(P, 'GET', '/api/bookings?date=2026-11-03&date=2030-01-01&x=1');
  check('date filter first', f.status === 200 && f.json.bookings.every((b) => b.date === '2026-11-03') && f.json.bookings.length === 5, f.text);
