      process.stdout.write(`${name} ${r.status} ${r.text}\n`);
    } catch (e) {
      process.stdout.write(`${name} ERR ${e.code}\n`);
    }
  }
}
process.stdout.write(`stderr: ${s.output.stderr}\n`);
await s.stop();
await removeDir(dir);

