      assert.equal(res.body.length, 0);
      assert.deepEqual(await listBookings(port), { bookings: [] });
      assertJsonError(await request(port, { method: 'DELETE', path: '/api/bookings/1' }), 404, 'booking not found');
    });

    it('never reuses an id after a delete', async () => {
      const second = await postBooking(port, validBooking());
      assert.equal(second.status, 201);
      assert.equal(second.json().id, 2);
      const del = await request(port, { method: 'DELETE', path: '/api/bookings/2' });
      assert.equal(del.status, 204);
      assert.equal(del.body.length, 0);
      const third = await postBooking(port, validBooking());
      assert.equal(third.status, 201);
      assert.equal(third.json().id, 3);
    });
